INSERT INTO Language_en_US(Tag,Text) VALUES
('TXT_KEY_CIV5_PSJ','The First Night'),
('TXT_KEY_CIVILOPEDIA_LEADERS_PSJ_PAUL','PaulsoaresJr'),
('TXT_KEY_CIV_PSJ_DESC','The First Night'),
('TXT_KEY_CIV_PSJ_SHORT_DESC','The First Night'),
('TXT_KEY_CIV_PSJ_ADJECTIVE','First-Night'),
('TXT_KEY_LEADER_PSJ_PAUL','PaulsoaresJr'),
('TXT_KEY_LEADER_PSJ_PAUL_PEDIA','PaulsoaresJr is the patient guide associated with early Minecraft survival tutorials. His friendly explanations made an unfamiliar world feel approachable: place a torch, find food, build a shelter, and try again tomorrow. This fictional civilization is an affectionate tribute to the children who learned alongside those videos and later discovered that ordinary play had become a treasured memory. It makes no claim that its invented cities or gameplay events are real history.'),
('TXT_KEY_CIVILOPEDIA_LEADERS_PSJ_PAUL_HEADING_1','A Patient Guide'),
('TXT_KEY_CIVILOPEDIA_LEADERS_PSJ_PAUL_TEXT_1','PaulsoaresJr is the patient guide associated with early Minecraft survival tutorials. His friendly explanations made an unfamiliar world feel approachable: place a torch, find food, build a shelter, and try again tomorrow. This fictional civilization is an affectionate tribute to the children who learned alongside those videos and later discovered that ordinary play had become a treasured memory. It makes no claim that its invented cities or gameplay events are real history.'),
('TXT_KEY_CIV_PSJ_PEDIA','The First Night represents a generation learning a once-mysterious game world, rather than a historical nation. A dirt shelter, a distant hill, and a first friendly encounter matter because they were new. Science and Culture grow from modest experiences whose emotional value increases with time.[NEWLINE][NEWLINE]Its Memories cannot be spent. Each records the era in which it happened. When a later era begins, every older Memory returns as Culture and Science: three of each per era of age. The original Starter House and Ancient Survivor preserve a tangible connection to the beginning.'),
('TXT_KEY_CIV5_PSJ_HEADING_1','The First Night'),
('TXT_KEY_CIV5_PSJ_TEXT_1','The First Night represents a generation learning a once-mysterious game world, rather than a historical nation. A dirt shelter, a distant hill, and a first friendly encounter matter because they were new. Science and Culture grow from modest experiences whose emotional value increases with time.[NEWLINE][NEWLINE]Its Memories cannot be spent. Each records the era in which it happened. When a later era begins, every older Memory returns as Culture and Science: three of each per era of age. The original Starter House and Ancient Survivor preserve a tangible connection to the beginning.'),
('TXT_KEY_CIV_PSJ_STRATEGY','Explore patiently, pursue Culture and Science, and let many small first experiences accumulate. Preserve your Ancient Survivor through upgrades, keep the original Home, and bring your explorers back after long journeys.[NEWLINE][NEWLINE]Most civilizations remember their greatest victories.[NEWLINE][NEWLINE]The First Night remembers something smaller.[NEWLINE][NEWLINE]The first shelter.[NEWLINE][NEWLINE]The first journey.[NEWLINE][NEWLINE]The first time the darkness stopped being frightening.[NEWLINE][NEWLINE]Players who explore patiently and allow their civilization to experience the world will accumulate Memories throughout the early game. These Memories initially provide modest rewards, but become increasingly valuable as centuries pass.[NEWLINE][NEWLINE]Do not rush.[NEWLINE][NEWLINE]There will be time for great cities later.[NEWLINE][NEWLINE]For now, enjoy not knowing what lies beyond the hill.'),
('TXT_KEY_TRAIT_PSJ_SHORT','How to Survive & Thrive'),
('TXT_KEY_TRAIT_PSJ_HELP','Ten first experiences become permanent Memories, each recording its era and granting a small instant yield. Every later era recalls each older Memory for 3 Culture and 3 Science per era of age. All instant yields scale with GameSpeed. Original Capital Starter House gains +1 Culture and +1 Happiness every two eras, up to +3 each. Ancient Survivors preserved into the Modern Era gain +1 Sight and +10% Defense. Explorers returning near the Capital after ten consecutive turns abroad earn 15 Culture once.'),
('TXT_KEY_UNIT_PSJ_SURVIVOR','Survivor'),
('TXT_KEY_UNIT_PSJ_SURVIVOR_HELP','Replaces Scout at the same Production cost and Combat Strength; 2 Movement. Retains Scout terrain abilities and upgrade path. Learning the World adds exploration XP and +5 healing in neutral/enemy territory under ordinary healing rules. Unique promotions survive upgrades.'),
('TXT_KEY_UNIT_PSJ_SURVIVOR_STRATEGY','Keep this curious explorer alive. Ruins grant 5 XP; attributed Natural Wonder discoveries grant 10 XP; the first three non-starting landmasses discovered by this Survivor lineage grant 10 XP each (maximum 30 XP); triggering First Journey grants 15 XP. Ten consecutive turns outside your territory followed by returning within two tiles of the Capital grants 15 Culture once, scaled to GameSpeed. Ancient Survivors still in your service from Modern onwards gain Been Here Since the Beginning.'),
('TXT_KEY_UNIT_PSJ_SURVIVOR_PEDIA','The original explorer was rarely impressive. It was simply the person who went beyond the next hill when no one knew what waited there. Its value comes from the journey, not battlefield supremacy. Years later, the old backpack and familiar footsteps are reminders of a world that once seemed endless.'),
('TXT_KEY_BUILDING_PSJ_STARTER_HOUSE','Starter House'),
('TXT_KEY_BUILDING_PSJ_STARTER_HOUSE_HELP','Replaces Monument at the same cost. +2 Culture. The first grants The First Shelter. The first Starter House in the original Capital gains +1 Culture and +1 Happiness per two eras of age, maximum +3 each. Its age persists if rebuilt; capture suspends the Home bonus until regained.'),
('TXT_KEY_BUILDING_PSJ_STARTER_HOUSE_STRATEGY','Build early in the original Capital. Home I, II and III are mutually exclusive bonus tiers at ages two, four and six eras. Relocating the Palace does not move Home. The bonus requires ownership and a Starter House in the original city. Razing ends Home permanently.'),
('TXT_KEY_BUILDING_PSJ_STARTER_HOUSE_PEDIA','Four walls. A roof. For tonight, that is enough. The first shelter is awkward and small, built before good materials or good taste. Later cities will dwarf it. Yet a magnificent skyline cannot replace the feeling of seeing that first door close against the darkness.'),
('TXT_KEY_PSJ_LEARNING','Learning the World'),
('TXT_KEY_PSJ_LEARNING_HELP','Exploration XP: 5 per ruin; 10 per attributed Natural Wonder; 10 for each of the first three non-starting landmasses discovered by this Survivor lineage (maximum 30 XP); 15 for First Journey. +5 healing in neutral and enemy territory when ordinary healing is permitted. Persists through upgrades. Return near the Capital after ten consecutive turns abroad for 15 Culture once, scaled with GameSpeed.'),
('TXT_KEY_PSJ_BEGINNING','Been Here Since the Beginning'),
('TXT_KEY_PSJ_BEGINNING_HELP','+1 Sight and +10% Defense. This Survivor existed in the Ancient Era and survived in your service into the Modern Era. The world has changed considerably.'),
('TXT_KEY_PSJ_HOME_1','Home 1'),
('TXT_KEY_PSJ_HOME_2','Home 2'),
('TXT_KEY_PSJ_HOME_3','Home 3'),
('TXT_KEY_PSJ_FIRST_SHELTER','The First Shelter'),
('TXT_KEY_PSJ_FIRST_SHELTER_NOTICE','Four walls. A roof. For tonight, that''s enough.[NEWLINE][NEWLINE]+{1_Num} [ICON_CULTURE] Culture / +{2_Num} [ICON_RESEARCH] Science / +{3_Num} [ICON_FOOD] Food'),
('TXT_KEY_PSJ_FIRST_NIGHT','The First Night'),
('TXT_KEY_PSJ_FIRST_NIGHT_NOTICE','The sun disappears beyond the horizon. Somehow, the world feels much larger in the dark.[NEWLINE][NEWLINE]+{1_Num} [ICON_CULTURE] Culture / +{2_Num} [ICON_RESEARCH] Science / +{3_Num} [ICON_FOOD] Food'),
('TXT_KEY_PSJ_FIRST_DANGER','The First Danger'),
('TXT_KEY_PSJ_FIRST_DANGER_NOTICE','You were afraid of them once.[NEWLINE][NEWLINE]+{1_Num} [ICON_CULTURE] Culture / +{2_Num} [ICON_RESEARCH] Science / +{3_Num} [ICON_FOOD] Food'),
('TXT_KEY_PSJ_FIRST_MINE','The First Mine'),
('TXT_KEY_PSJ_FIRST_MINE_NOTICE','There''s something beneath your feet. You just have to dig.[NEWLINE][NEWLINE]+{1_Num} [ICON_CULTURE] Culture / +{2_Num} [ICON_RESEARCH] Science / +{3_Num} [ICON_FOOD] Food'),
('TXT_KEY_PSJ_FIRST_HARVEST','The First Harvest'),
('TXT_KEY_PSJ_FIRST_HARVEST_NOTICE','For the first time, survival begins to feel sustainable.[NEWLINE][NEWLINE]+{1_Num} [ICON_CULTURE] Culture / +{2_Num} [ICON_RESEARCH] Science / +{3_Num} [ICON_FOOD] Food'),
('TXT_KEY_PSJ_FIRST_JOURNEY','The First Journey'),
('TXT_KEY_PSJ_FIRST_JOURNEY_NOTICE','Home disappears behind the hills.[NEWLINE][NEWLINE]+{1_Num} [ICON_CULTURE] Culture / +{2_Num} [ICON_RESEARCH] Science / +{3_Num} [ICON_FOOD] Food'),
('TXT_KEY_PSJ_FIRST_FRIEND','The First Friend'),
('TXT_KEY_PSJ_FIRST_FRIEND_NOTICE','So we weren''t alone after all.[NEWLINE][NEWLINE]+{1_Num} [ICON_CULTURE] Culture / +{2_Num} [ICON_RESEARCH] Science / +{3_Num} [ICON_FOOD] Food'),
('TXT_KEY_PSJ_FIRST_WONDER','The First Wonder'),
('TXT_KEY_PSJ_FIRST_WONDER_NOTICE','You didn''t know the world could contain something like this.[NEWLINE][NEWLINE]+{1_Num} [ICON_CULTURE] Culture / +{2_Num} [ICON_RESEARCH] Science / +{3_Num} [ICON_FOOD] Food'),
('TXT_KEY_PSJ_BEYOND_HOME','A World Beyond Home'),
('TXT_KEY_PSJ_BEYOND_HOME_NOTICE','There was a time when one little home was the entire world.[NEWLINE][NEWLINE]+{1_Num} [ICON_CULTURE] Culture / +{2_Num} [ICON_RESEARCH] Science / +{3_Num} [ICON_FOOD] Food'),
('TXT_KEY_PSJ_SOMETHING_NEW','Something New'),
('TXT_KEY_PSJ_SOMETHING_NEW_NOTICE','Yesterday''s mysteries become tomorrow''s knowledge.[NEWLINE][NEWLINE]+{1_Num} [ICON_CULTURE] Culture / +{2_Num} [ICON_RESEARCH] Science / +{3_Num} [ICON_FOOD] Food'),
('TXT_KEY_PSJ_MEMORIES','Memories'),
('TXT_KEY_PSJ_MEMORIES_TEXT','Each Memory is earned once per player, cannot be spent, and permanently records its acquisition era. Recall rewards are 3 Culture and 3 Science multiplied by current era minus acquisition era. Only positive-age Memories are recalled. Instant Culture, Science and Food use their respective GameSpeed percentages.[NEWLINE][NEWLINE]The First Shelter: Your first Starter House. 10 Culture.[NEWLINE][NEWLINE]The First Night: The first full turn after founding the Capital. 5 Culture and 5 Science.[NEWLINE][NEWLINE]The First Danger: Your first Barbarian kill. 10 Culture.[NEWLINE][NEWLINE]The First Mine: Complete your first Mine. 10 Science.[NEWLINE][NEWLINE]The First Harvest: Complete a valid improvement on a visible bonus or luxury resource whose base resource yield includes Food. 5 Food in the Capital and 5 Culture.[NEWLINE][NEWLINE]The First Journey: Any unit reaches 10 tiles from the current Capital, reduced on tiny maps. 10 Culture and 10 Science.[NEWLINE][NEWLINE]The First Friend: Meet another major civilization or City-State. 10 Culture.[NEWLINE][NEWLINE]The First Wonder: Discover a Natural Wonder. 15 Culture and 10 Science.[NEWLINE][NEWLINE]A World Beyond Home: Own two cities. 15 Culture.[NEWLINE][NEWLINE]Something New: Enter the Classical Era. 10 Science and 10 Culture.'),
('TXT_KEY_PSJ_OLD_MEMORIES','Old Memories'),
('TXT_KEY_PSJ_OLD_MEMORIES_TEXT','The world has changed, but you still remember how it began.[NEWLINE][NEWLINE]{1_Num} Memories remembered.[NEWLINE]+{2_Num} [ICON_CULTURE] Culture[NEWLINE]+{3_Num} [ICON_RESEARCH] Science'),
('TXT_KEY_PSJ_HOME_AGAIN','Home Again'),
('TXT_KEY_PSJ_HOME_AGAIN_TEXT','The familiar lights appear beyond the trees.[NEWLINE][NEWLINE]It is strange how much smaller home looks after seeing the world.[NEWLINE][NEWLINE]And stranger still how good it feels to return.[NEWLINE][NEWLINE]+{1_Num} [ICON_CULTURE] Culture'),
('TXT_KEY_PSJ_ERA_CLASSICAL','The World Is Getting Bigger'),
('TXT_KEY_PSJ_ERA_CLASSICAL_TEXT','Once, reaching the next hill felt like an expedition.[NEWLINE][NEWLINE]Now there are roads where wilderness once stood.[NEWLINE][NEWLINE]There is still much to learn.'),
('TXT_KEY_PSJ_ERA_MEDIEVAL','Survive. Then Thrive.'),
('TXT_KEY_PSJ_ERA_MEDIEVAL_TEXT','Survival once occupied every thought.[NEWLINE][NEWLINE]Food. Shelter. Darkness.[NEWLINE][NEWLINE]Now there is time to build something greater.'),
('TXT_KEY_PSJ_ERA_RENAISSANCE','How Far We''ve Come'),
('TXT_KEY_PSJ_ERA_RENAISSANCE_TEXT','Do you remember when the borders of the world were simply the furthest place you had explored?'),
('TXT_KEY_PSJ_ERA_INDUSTRIAL','The Old House'),
('TXT_KEY_PSJ_ERA_INDUSTRIAL_TEXT','Smoke rises above great cities. Machines cross lands that once took days to traverse.[NEWLINE][NEWLINE]Somewhere beneath all of it sits the place where this adventure began.'),
('TXT_KEY_PSJ_ERA_INFORMATION','Do You Remember?'),
('TXT_KEY_PSJ_ERA_INFORMATION_TEXT','There was a time when you did not know what waited beyond the hill.[NEWLINE][NEWLINE]When darkness meant danger.[NEWLINE][NEWLINE]When finding something new was enough to make you run and tell someone.[NEWLINE][NEWLINE]You did not know the recipes.[NEWLINE][NEWLINE]You did not know the world.[NEWLINE][NEWLINE]You didn''t even know what you were supposed to do.[NEWLINE][NEWLINE]And perhaps that was what made it wonderful.[NEWLINE][NEWLINE]You survived.[NEWLINE][NEWLINE]You explored.[NEWLINE][NEWLINE]You learned.[NEWLINE][NEWLINE]And somewhere along the way, you thrived.'),
('TXT_KEY_PSJ_DAWN_OF_MAN','PaulsoaresJr, patient guide of a generation...[NEWLINE][NEWLINE]Before the great cities, before the machines, before anyone knew every secret hidden within the world, there was uncertainty.[NEWLINE][NEWLINE]Night was frightening. Caves were mysterious. Every distant mountain promised something undiscovered.[NEWLINE][NEWLINE]Millions would eventually come to know this world by heart.[NEWLINE][NEWLINE]But once, they were children seeing it for the first time.[NEWLINE][NEWLINE]And when they needed someone to show them how to place the first torch, build the first shelter, and survive until morning...[NEWLINE][NEWLINE]You were there.[NEWLINE][NEWLINE]PaulsoaresJr, will you once again guide your people into the unknown?[NEWLINE][NEWLINE]Will you teach them not merely how to survive... but how to thrive?'),
('TXT_KEY_PSJ_CITY_00','Home'),
('TXT_KEY_PSJ_CITY_01','Spawn'),
('TXT_KEY_PSJ_CITY_02','The First Hill'),
('TXT_KEY_PSJ_CITY_03','Green Valley'),
('TXT_KEY_PSJ_CITY_04','Old Woods'),
('TXT_KEY_PSJ_CITY_05','Torchlight'),
('TXT_KEY_PSJ_CITY_06','Stone Hollow'),
('TXT_KEY_PSJ_CITY_07','Far Ridge'),
('TXT_KEY_PSJ_CITY_08','Morning Fields'),
('TXT_KEY_PSJ_CITY_09','Deep Cavern'),
('TXT_KEY_PSJ_CITY_10','Red Mountain'),
('TXT_KEY_PSJ_CITY_11','Beyond the River'),
('TXT_KEY_PSJ_CITY_12','Northwood'),
('TXT_KEY_PSJ_CITY_13','Sunset Plains'),
('TXT_KEY_PSJ_CITY_14','New Horizon'),
('TXT_KEY_PSJ_CITY_15','Quiet Shore'),
('TXT_KEY_PSJ_CITY_16','Birch Clearing'),
('TXT_KEY_PSJ_CITY_17','Old Footpath'),
('TXT_KEY_PSJ_CITY_18','Lantern Ridge'),
('TXT_KEY_PSJ_CITY_19','Last Light'),
('TXT_KEY_PSJ_SPY_00','Alex'),
('TXT_KEY_PSJ_SPY_01','Robin'),
('TXT_KEY_PSJ_SPY_02','Sam'),
('TXT_KEY_PSJ_SPY_03','Morgan'),
('TXT_KEY_PSJ_SPY_04','Jamie'),
('TXT_KEY_PSJ_SPY_05','Rowan'),
('TXT_KEY_PSJ_SPY_06','Casey'),
('TXT_KEY_PSJ_SPY_07','Taylor'),
('TXT_KEY_PSJ_DIPLO_FIRST_GREETING_1','Oh! Hello there. Looks like you''ve found us. There''s quite a world out there, isn''t there? Take your time. You''ll figure it out.'),
('TXT_KEY_PSJ_DIPLO_GREETING_NEUTRAL_HELLO_1','Good to see you again. Found anything interesting out there?'),
('TXT_KEY_PSJ_DIPLO_GREETING_HOSTILE_HELLO_1','Let''s keep this conversation civil. We all have a home to return to.'),
('TXT_KEY_PSJ_DIPLO_DOW_GENERIC_1','I''d much rather be building something. Unfortunately, you''ve left us little choice.'),
('TXT_KEY_PSJ_DIPLO_ATTACKED_HOSTILE_1','Well, this is a lesson I hoped we wouldn''t need. We''ll defend our home.'),
('TXT_KEY_PSJ_DIPLO_DEFEATED_1','Well... that didn''t quite go according to plan. Still, every world teaches you something.'),
('TXT_KEY_PSJ_DIPLO_DENOUNCE_1','There''s surviving, and then there''s making the world worse for everyone else. You''ve chosen the latter.'),
('TXT_KEY_PSJ_DIPLO_RESPONSE_TO_BEING_DENOUNCED_1','That''s disappointing. I''d hoped we could learn to get along.'),
('TXT_KEY_PSJ_DIPLO_PEACE_OFFER_1','Let''s give everyone a chance to come home.'),
('TXT_KEY_PSJ_DIPLO_TRADE_ACCEPT_ACCEPTABLE_1','That seems fair. Thank you, neighbour.'),
('TXT_KEY_PSJ_DIPLO_TRADE_REJECT_UNACCEPTABLE_1','That doesn''t quite work for us. Perhaps try another arrangement.'),
('TXT_KEY_PSJ_DIPLO_TRADE_AI_MAKES_OFFER_1','I''ve learned that the world becomes considerably easier when neighbours help one another.'),
('TXT_KEY_PSJ_DIPLO_GENERIC_1','There''s plenty to learn from one another. Let''s see what we can work out.');
INSERT INTO Diplomacy_Responses(LeaderType,ResponseType,Response,Bias) SELECT 'LEADER_PSJ_PAUL',ResponseType,'TXT_KEY_PSJ_DIPLO_GENERIC%',Bias FROM Diplomacy_Responses WHERE LeaderType='LEADER_WASHINGTON' GROUP BY ResponseType;
